import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Plus, Trash2 } from 'lucide-react';
import { motion } from 'framer-motion';
import toast from 'react-hot-toast';
import API from '../utils/api';
import '../styles/group-create.css';

export default function CreateGroup() {
  const [groupName, setGroupName] = useState('');
  const [members, setMembers] = useState(['']);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const { user } = useAuth();

  const handleAddMember = () => {
    setMembers([...members, '']);
  };

  const handleRemoveMember = (index) => {
    setMembers(members.filter((_, i) => i !== index));
  };

  const handleUpdateMember = (index, value) => {
    const newMembers = [...members];
    newMembers[index] = value;
    setMembers(newMembers);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!groupName.trim()) {
      toast.error('Please enter a group name');
      return;
    }

    const validMembers = members.filter(m => m.trim()).map(m => m.trim());
    if (validMembers.length === 0) {
      toast.error('Please add at least one member');
      return;
    }

    setLoading(true);
    try {
      const res = await API.post('/groups', {
        name: groupName,
        members: validMembers
      });
      toast.success('Group created successfully!');
      navigate(`/group/${res.data._id}`);
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to create group');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="create-group-page">
      <motion.div
        className="create-group-container"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <button className="btn-back" onClick={() => navigate('/dashboard')}>
          <ArrowLeft size={20} />
          Back
        </button>

        <div className="create-form-wrapper">
          <div className="form-header">
            <h1>Create New Group</h1>
            <p>Invite your friends and start tracking expenses</p>
          </div>

          <form onSubmit={handleSubmit} className="create-form">
            <div className="form-group">
              <label>Group Name</label>
              <input
                type="text"
                placeholder="e.g., Weekend Trip, Roommates, etc."
                value={groupName}
                onChange={(e) => setGroupName(e.target.value)}
                autoFocus
              />
            </div>

            <div className="form-group">
              <label>Members</label>
              <p className="form-hint">Add names or emails of group members</p>
              <div className="members-input-list">
                {members.map((member, i) => (
                  <motion.div
                    key={i}
                    className="member-input-row"
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                  >
                    <span className="member-number">{i + 1}</span>
                    <input
                      type="text"
                      placeholder="Name or email"
                      value={member}
                      onChange={(e) => handleUpdateMember(i, e.target.value)}
                    />
                    {members.length > 1 && (
                      <button
                        type="button"
                        className="remove-member-btn"
                        onClick={() => handleRemoveMember(i)}
                      >
                        <Trash2 size={18} />
                      </button>
                    )}
                  </motion.div>
                ))}
              </div>
              <button type="button" className="btn-secondary" onClick={handleAddMember}>
                <Plus size={20} />
                Add Member
              </button>
            </div>

            <div className="form-group info-card">
              <p>💡 You'll be automatically added to this group</p>
            </div>

            <div className="form-actions">
              <button type="button" className="btn-secondary" onClick={() => navigate('/dashboard')}>
                Cancel
              </button>
              <button type="submit" className="btn-primary" disabled={loading}>
                {loading ? (
                  <>
                    <span className="spinner"></span>
                    Creating group...
                  </>
                ) : (
                  <>Create Group</>
                )}
              </button>
            </div>
          </form>
        </div>

        <motion.div
          className="create-illustration"
          initial={{ opacity: 0, x: 40 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5, delay: 0.2 }}
        >
          <div className="illustration-card">
            <div className="illustration-icon">👥</div>
            <h3>Group Benefits</h3>
            <ul className="benefits-list">
              <li>Track shared expenses</li>
              <li>Automatic calculations</li>
              <li>Easy settlements</li>
              <li>Transaction history</li>
              <li>Fair cost splitting</li>
            </ul>
          </div>
        </motion.div>
      </motion.div>
    </div>
  );
}
